fn shared_finish_inductive(pre: Self, post: Self, r: int) {
}

input.newString:
#[inductive(shared_finish)]
fn shared_finish_inductive(pre: Self, post: Self, r: int) {
    // Show that shared_counts_agree invariant is preserved
    assert forall |rr| 0 <= rr < post.rc_width implies
        #[trigger] post.ref_counts.index(rr) ==
            post.shared_pending.count(rr) as int +
                Self::filter_r(post.shared_guard, rr).len() as int
    by {
        // Case 1: rr != r (the affected index)
        if rr != r {
            // Since we only modified counts at index r, all other indices remain unchanged
            assert(pre.ref_counts.index(rr) == post.ref_counts.index(rr));
            assert(pre.shared_pending.count(rr) == post.shared_pending.count(rr));
            assert(Self::filter_r(pre.shared_guard, rr).len() == Self::filter_r(post.shared_guard, rr).len());

            // By the inductive hypothesis (pre-state satisfies the invariant)
            assert(pre.ref_counts.index(rr) ==
                pre.shared_pending.count(rr) as int +
                    Self::filter_r(pre.shared_guard, rr).len() as int);
        } else {
            // Case 2: rr == r (the affected index)
            // In the transition:
            // - shared_pending.count(r) decreased by 1
            // - Self::filter_r(shared_guard, r).len() increased by 1
            // So the sum remains the same

            assert(pre.shared_pending.count(r) == post.shared_pending.count(r) + 1);
            assert(Self::filter_r(post.shared_guard, r).len() == Self::filter_r(pre.shared_guard, r).len() + 1);
            assert(pre.ref_counts.index(r) == post.ref_counts.index(r));

            // By the inductive hypothesis (pre-state satisfies the invariant)
            assert(pre.ref_counts.index(r) ==
                pre.shared_pending.count(r) as int +
                    Self::filter_r(pre.shared_guard, r).len() as int);
        }
    }
}

