#[inductive(shared_finish)]
fn shared_finish_inductive(pre: Self, post: Self, r: int) {
    // Show that shared_counts_agree invariant is preserved
    assert forall |rr| 0 <= rr < post.rc_width implies
        #[trigger] post.ref_counts.index(rr) ==
            post.shared_pending.count(rr) as int +
                Self::filter_r(post.shared_guard, rr).len() as int
    by {
        // From the transition definition:
        // 1. post.ref_counts.index(rr) == pre.ref_counts.index(rr) (unchanged)
        // 2. post.shared_pending.count(rr) == pre.shared_pending.count(rr) - (if rr == r then 1 else 0)
        // 3. post.shared_guard == pre.shared_guard.insert((r, t)) where t = pre.storage.get_Some_0()
        // 4. Self::filter_r(post.shared_guard, rr).len() == Self::filter_r(pre.shared_guard, rr).len() + (if rr == r then 1 else 0)

        assert(post.ref_counts.index(rr) == pre.ref_counts.index(rr));

        // Case analysis on whether rr equals r
        if rr != r {
            // Elements with key != r are unaffected
            assert(post.shared_pending.count(rr) == pre.shared_pending.count(rr));
            assert(Self::filter_r(post.shared_guard, rr).len() == Self::filter_r(pre.shared_guard, rr).len());

            // By inductive hypothesis
            assert(pre.ref_counts.index(rr) ==
                pre.shared_pending.count(rr) as int +
                    Self::filter_r(pre.shared_guard, rr).len() as int);
        } else {
            // For the key r that was modified:
            // - shared_pending count decreases by 1
            // - filter_r length increases by 1
            // So the sum remains constant
            assert(post.shared_pending.count(rr) == pre.shared_pending.count(rr) - 1);
            assert(Self::filter_r(post.shared_guard, rr).len() == Self::filter_r(pre.shared_guard, rr).len() + 1);

            // By inductive hypothesis
            assert(pre.ref_counts.index(rr) ==
                pre.shared_pending.count(rr) as int +
                    Self::filter_r(pre.shared_guard, rr).len() as int);

            // Therefore:
            // post.ref_counts.index(rr) 
            // = pre.ref_counts.index(rr)  [ref_counts unchanged]
            // = pre.shared_pending.count(rr) + Self::filter_r(pre.shared_guard, rr).len()  [inductive hyp]
            // = (post.shared_pending.count(rr) + 1) + (Self::filter_r(post.shared_guard, rr).len() - 1)  [by above eqs]
            // = post.shared_pending.count(rr) + Self::filter_r(post.shared_guard, rr).len()  [simplified]
        }
    }
}

