#[inductive(shared_finish)]
fn shared_finish_inductive(pre: Self, post: Self, r: int) {
    // Show that shared_counts_agree invariant is preserved
    assert forall |rr| 0 <= rr < post.rc_width implies
        #[trigger] post.ref_counts.index(rr) ==
            post.shared_pending.count(rr) as int +
                Self::filter_r(post.shared_guard, rr).len() as int
    by {
        // By inductive hypothesis (pre-state satisfies the invariant)
        assert(pre.ref_counts.index(rr) ==
            pre.shared_pending.count(rr) as int +
                Self::filter_r(pre.shared_guard, rr).len() as int);

        // In the shared_finish transition:
        // - post.ref_counts.index(rr) = pre.ref_counts.index(rr) (unchanged)
        // - post.shared_pending.count(rr) = pre.shared_pending.count(rr) - (if rr == r then 1 else 0)
        // - post.shared_guard = pre.shared_guard.insert((r, pre.storage.get_Some_0()))
        // - Self::filter_r(post.shared_guard, rr).len() = Self::filter_r(pre.shared_guard, rr).len() + (if rr == r then 1 else 0)

        // Prove the post-state invariant holds
        if rr != r {
            // For indices other than r, nothing changes
            assert(post.shared_pending.count(rr) == pre.shared_pending.count(rr));
            assert(Self::filter_r(post.shared_guard, rr).len() == Self::filter_r(pre.shared_guard, rr).len());
            assert(post.ref_counts.index(rr) == pre.ref_counts.index(rr));
            // Therefore by substitution:
            assert(post.ref_counts.index(rr) ==
                post.shared_pending.count(rr) as int +
                    Self::filter_r(post.shared_guard, rr).len() as int);
        } else {
            // For index r, we need to show the counts still agree:
            // pre.ref_counts.index(r) = pre.shared_pending.count(r) + Self::filter_r(pre.shared_guard, r).len()
            // post.ref_counts.index(r) = pre.ref_counts.index(r)
            // post.shared_pending.count(r) = pre.shared_pending.count(r) - 1  
            // Self::filter_r(post.shared_guard, r).len() = Self::filter_r(pre.shared_guard, r).len() + 1
            //
            // So we have:
            // post.ref_counts.index(r) 
            // = pre.ref_counts.index(r)
            // = pre.shared_pending.count(r) + Self::filter_r(pre.shared_guard, r).len()
            // = (pre.shared_pending.count(r) - 1) + (Self::filter_r(pre.shared_guard, r).len() + 1)
            // = post.shared_pending.count(r) + Self::filter_r(post.shared_guard, r).len()
            assert(post.shared_pending.count(rr) == pre.shared_pending.count(rr) - 1);
            assert(Self::filter_r(post.shared_guard, rr).len() == Self::filter_r(pre.shared_guard, rr).len() + 1);
            assert(post.ref_counts.index(rr) == pre.ref_counts.index(rr));
            assert(post.ref_counts.index(rr) ==
                post.shared_pending.count(rr) as int +
                    Self::filter_r(post.shared_guard, rr).len() as int);
        }
    }
}

