            // = pre.shared_pending.count(r) + Self::filter_r(pre.shared_guard, r).len()  [inductive hyp]
            // = (pre.shared_pending.count(r) - 1) + (Self::filter_r(pre.shared_guard, r).len() + 1)  [arithmetic]
            // = post.shared_pending.count(r) + Self::filter_r(post.shared_guard, r).len()  [definitions]

            assert(post.ref_counts.index(rr) ==
                post.shared_pending.count(rr) as int +
                    Self::filter_r(post.shared_guard, rr).len() as int);
        }
    }
}

