        #[trigger] post.ref_counts.index(rr) ==
            post.shared_pending.count(rr) as int +
                Self::filter_r(post.shared_guard, rr).len() as int
    by {
        // By inductive hypothesis (pre-state satisfies the invariant)
        assert(pre.ref_counts.index(rr) ==
            pre.shared_pending.count(rr) as int +
                Self::filter_r(pre.shared_guard, rr).len() as int);

        // Transition facts:
        assert(post.ref_counts.index(rr) == pre.ref_counts.index(rr));

        // Case analysis:
        if rr != r {
            // For indices other than r, nothing changes:
            assert(post.shared_pending.count(rr) == pre.shared_pending.count(rr));
            assert(Self::filter_r(post.shared_guard, rr).len() == Self::filter_r(pre.shared_guard, rr).len());

            // Now we can prove the target assertion by substitution:
            calc! {
                (==)
                post.ref_counts.index(rr);
                pre.ref_counts.index(rr); {}
                pre.shared_pending.count(rr) + Self::filter_r(pre.shared_guard, rr).len(); {
                    assert(pre.ref_counts.index(rr) ==
                        pre.shared_pending.count(rr) + Self::filter_r(pre.shared_guard, rr).len());
                }
                post.shared_pending.count(rr) + Self::filter_r(post.shared_guard, rr).len(); {
                    assert(post.shared_pending.count(rr) == pre.shared_pending.count(rr));
                    assert(Self::filter_r(post.shared_guard, rr).len() == Self::filter_r(pre.shared_guard, rr).len());
                }
            }
        } else {
            // For index r:
            assert(post.shared_pending.count(rr) == pre.shared_pending.count(rr) - 1);
            assert(Self::filter_r(post.shared_guard, rr).len() == Self::filter_r(pre.shared_guard, rr).len() + 1);

            // Now we can prove the target assertion:
            calc! {
                (==)
                post.ref_counts.index(rr);
                pre.ref_counts.index(rr); {}
                pre.shared_pending.count(rr) + Self::filter_r(pre.shared_guard, rr).len(); {
                    assert(pre.ref_counts.index(rr) ==
                        pre.shared_pending.count(rr) + Self::filter_r(pre.shared_guard, rr).len());
                }
                (pre.shared_pending.count(rr) - 1) + (Self::filter_r(pre.shared_guard, rr).len() + 1); {}
                post.shared_pending.count(rr) + Self::filter_r(post.shared_guard, rr).len(); {
                    assert(post.shared_pending.count(rr) == pre.shared_pending.count(rr) - 1);
                    assert(Self::filter_r(post.shared_guard, rr).len() == Self::filter_r(pre.shared_guard, rr).len() + 1);
                }
            }
        }
    }
}

