        assert(pre.ref_counts.index(rr) ==
            pre.shared_pending.count(rr) as int +
                Self::filter_r(pre.shared_guard, rr).len() as int);

        // Transition facts:
        assert(post.ref_counts.index(rr) == pre.ref_counts.index(rr));

        // Case analysis:
        if rr != r {
            // For indices other than r, nothing changes in the transition:
            assert(post.shared_pending.count(rr) == pre.shared_pending.count(rr));
            assert(Self::filter_r(post.shared_guard, rr).len() == Self::filter_r(pre.shared_guard, rr).len());

            // Using equations:
            // (1) post.ref_counts.index(rr) = pre.ref_counts.index(rr)  [transition fact]
            // (2) pre.ref_counts.index(rr) = pre.shared_pending.count(rr) + Self::filter_r(pre.shared_guard, rr).len()  [inductive hyp]
            // (3) post.shared_pending.count(rr) = pre.shared_pending.count(rr)  [transition fact]
            // (4) Self::filter_r(post.shared_guard, rr).len() = Self::filter_r(pre.shared_guard, rr).len()  [transition fact]
            //
            // Combining:
            // post.ref_counts.index(rr) 
            // = pre.ref_counts.index(rr)  [by (1)]
            // = pre.shared_pending.count(rr) + Self::filter_r(pre.shared_guard, rr).len()  [by (2)]
            // = post.shared_pending.count(rr) + Self::filter_r(post.shared_guard, rr).len()  [by (3),(4)]
            assert(post.ref_counts.index(rr) ==
                post.shared_pending.count(rr) as int +
                    Self::filter_r(post.shared_guard, rr).len() as int);
        } else {
            // For index r, the transition modifies the counts:
            assert(post.shared_pending.count(rr) == pre.shared_pending.count(rr) - 1);
            assert(Self::filter_r(post.shared_guard, rr).len() == Self::filter_r(pre.shared_guard, rr).len() + 1);

            // Using equations:
            // (1) post.ref_counts.index(rr) = pre.ref_counts.index(rr)  [transition fact]
