            // (3) post.shared_pending.count(rr) = pre.shared_pending.count(rr) - 1  [transition fact]
            // (4) Self::filter_r(post.shared_guard, rr).len() = Self::filter_r(pre.shared_guard, rr).len() + 1  [transition fact]
            //
            // Combining:
            // post.ref_counts.index(rr) 
            // = pre.ref_counts.index(rr)  [by (1)]
            // = pre.shared_pending.count(rr) + Self::filter_r(pre.shared_guard, rr).len()  [by (2)]
            // = (pre.shared_pending.count(rr) - 1) + (Self::filter_r(pre.shared_guard, rr).len() + 1)  [arithmetic]
            // = post.shared_pending.count(rr) + Self::filter_r(post.shared_guard, rr).len()  [by (3),(4)]
            assert(post.ref_counts.index(rr) ==
                post.shared_pending.count(rr) as int +
                    Self::filter_r(post.shared_guard, rr).len() as int);
        }
    }
}

